fn min_inspectors(n: i8, d: i8) -> i8 {
    // Promote to a wider type to avoid any overflow concerns.
    let n = n as i32;
    let d = d as i32;

    // Each inspector covers at most k = 2*d + 1 items contiguously.
    let k = 2 * d + 1;

    // Ceiling division for positive integers: (n + k - 1) / k
    let res = (n + k - 1) / k;

    res as i8
}

